package com.vahotel.web;import com.vahotel.repo.RoomRepository;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.GetMapping;
@Controller public class PageController {private final RoomRepository rooms;public PageController(RoomRepository r){rooms=r;}@GetMapping("/") public String home(Model m){m.addAttribute("rooms",rooms.findByActiveTrue());return "index";}@GetMapping("/rooms") public String rooms(Model m){m.addAttribute("rooms",rooms.findByActiveTrue());return "rooms";}@GetMapping("/login") public String login(){return "login";}}
